mapper.select:
select c.* from sh_comment c left join sh_user u on c.buyer_id = u.id left join sh_idle_item i on c.idle_id = i.id
and ( c.content like concat('%', #{searchValue}, '%') or c.id = #{searchValue} or u.nickname like concat('%', #{searchValue}, '%') or i.idle_name like concat('%', #{searchValue}, '%') )
order by c.create_time desc limit #{begin}, #{nums}
